#include "opensim/scene/inventory_drop_permission.hpp"
#include <iostream>
using namespace opensim;using namespace scene;
namespace {
framework::Uuid id(int n){auto s=std::to_string(n);return framework::Uuid("11223344-5566-7788-99aa-"+std::string(12-s.size(),'0')+s);}
std::string probe(int mode,int failure){auto bit=[&](int n){return (mode&n)!=0;};std::string trace;auto step=[&](int n){trace+='|'+std::to_string(n);if(failure==n)throw std::runtime_error("injected");};services::InventoryItem item;item.inventory_type=bit(1024)?10:7;item.owner=id(bit(2048)?9:1);item.current_permissions=bit(4096)?0:0x2000;std::optional<InventoryDropPresence> presence=InventoryDropPresence{id(bit(512)?9:1),bit(2),bit(128)};std::optional<InventoryDropPart> part=InventoryDropPart{id(3),id(1),!bit(16),bit(32),bit(256)?0u:0x80000u};if(bit(1))presence.reset();if(bit(4))part.reset();InventoryDropPermissionBackend b;b.debug=[&]{step(1);};b.bypass=[&]{step(2);return bit(64);};b.root_flags=[&](const auto&){step(3);return bit(8192)?0x10000u:0;};b.object_permissions=[&](auto,const auto&,bool value){if(!value)throw std::runtime_error("missing permission argument");step(4);return bit(16384)?0u:0x4000u;};std::string result;try{result=can_drop_object_inventory(bit(8)?nullptr:&item,presence,part,b)?"1":"0";}catch(...){result="THROW";}return result+trace;}
}
int main(int argc,char** argv){try{if(argc>1&&std::string_view(argv[1])=="--probe"){int mode,failure;while(std::cin>>mode>>failure)std::cout<<probe(mode,failure)<<'\n';return 0;}int n=0;auto check=[&](bool v,const char* s){++n;if(!v)throw std::runtime_error(s);};check(probe(0,0)=="1|1|2|3|4","owner modify");check(probe(1|64,0)=="0|1","missing presence before bypass");check(probe(64|256,0)=="1|1|2","bypass before lock");check(probe(512|1024|8192,0)=="0|1|2","foreign script before allow drop");check(probe(2048|4096|8192,0)=="0|1|2","foreign item needs transfer");check(probe(8192|16384,0)=="1|1|2|3","allow drop bypasses modify");std::cout<<"PASS: "<<n<<" inventory drop permission checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
